#!/usr/bin/env python3
"""Writes sounds/SONGS.md: every music clip (songs, themes, fanfares, jingles) with its source."""
import json, re, collections
c = json.load(open('sounds/clips.json'))
by = {x['f']: x for x in c}
def row(f, title, who):
    x = by[f]; return f"| `{f}` | {title} | {who} | {x['d']} s | [{x['src'].split(':')[0]}]({x['url']}) |"
out = ["# Songs and music clips on the turn button / soundboard\n",
"Generated by `python3 tools/sounds/make_songs.py` from `sounds/clips.json`. Real songs first (copyrighted, not CC0),",
"then CC0 jingle and fanfare packs from OpenGameArt. Composer credits are from general knowledge, not from the source pages.\n",
"## Real songs and themes\n", "| File | Piece | Artist / composer | Length | Source |", "| --- | --- | --- | --- | --- |"]
cope = {'alleluia':'Alleluia (Greater Than Us All)','come-to-jesus':'Come to Jesus (Face to Face)','eden-s-garden':"Eden's Garden (LDS Superhits of the '90s)",
 'gethsemane':'Gethsemane (Shepherd of My Soul)','his-hands':'His Hands (Greater Than Us All)','i-will-not-be-still':'I Will Not Be Still (EFY 1999)',
 'never-a-better-hero':'Never a Better Hero (Greater Than Us All)','the-carpenter-s-son':"The Carpenter's Son (EFY Best of Vol. 2)",
 'we-believe':'We Believe (EFY 2002)','what-have-i-done-with-his-name':'What Have I Done With His Name? (EFY Best of Vol. 2)'}
for k, t in cope.items(): out.append(row('cope-'+k, t, 'Kenneth Cope (Apple iTunes 30 s preview)'))
real = [('ff-chocobo-theme','Chocobo theme','Nobuo Uematsu, Final Fantasy'),('ff6-terra-theme',"Terra's Theme",'Nobuo Uematsu, Final Fantasy VI'),
 ('ff7-battle-theme','Battle theme','Nobuo Uematsu, Final Fantasy VII'),('ff7-one-winged-angel','One-Winged Angel','Nobuo Uematsu, Final Fantasy VII'),
 ('ff7-one-winged-angel-edit','One-Winged Angel (edit)','Nobuo Uematsu, Final Fantasy VII'),
 ('ff-fanfare','Final Fantasy fanfare','Nobuo Uematsu, Final Fantasy'),('ff1-victory-fanfare','Victory Fanfare','Nobuo Uematsu, Final Fantasy'),
 ('ff4-victory-fanfare','Fanfare of Victory','Nobuo Uematsu, Final Fantasy IV'),('ff7-victory-fanfare','Victory Fanfare','Nobuo Uematsu, Final Fantasy VII'),
 ('ff9-victory-fanfare','Victory Fanfare','Nobuo Uematsu, Final Fantasy IX'),('ff11-victory-fanfare','Victory','Final Fantasy XI'),
 ('ff-victory-orchestral','Victory (orchestral)','Final Fantasy'),('ff7r-barret-fanfare','Barret fanfare','Final Fantasy VII Remake'),
 ('long/sw-imperial-march','The Imperial March','John Williams, Star Wars'),('long/sw-cantina','Cantina Band','John Williams, Star Wars'),
 ('long/doom-e1m1',"At Doom's Gate (E1M1)",'Bobby Prince, Doom'),('long/duke-theme','Duke Nukem Forever theme (Grabbag mix)','Duke Nukem'),
 ('duke-riff','Duke Nukem riff','Duke Nukem'),('long/gow-theme','Gears of War theme','Gears of War'),('long/gow-locust-theme','Locust Theme','Doctor Nowhere, Gears of War'),
 ('long/jeopardy-think','Final Jeopardy think music','Jeopardy!'),('long/megaman2-victory','Mega Man 2 victory','Capcom'),
 ('megaman3-stage-clear','Mega Man 3 stage clear','Capcom'),('long/megaman3-proto-man-whistle','Proto Man\'s Whistle','Capcom, Mega Man 3'),
 ('megaman-game-over','Mega Man game over','Capcom'),('megaman2-game-over','Mega Man 2 game over','Capcom'),
 ('zelda-item-get','Item get jingle','Nintendo, Zelda'),('mario-death','Mario death jingle','Nintendo'),
 ('trek-opening-chime','Star Trek opening chime','Star Trek'),('long/trek-tos-chime','TOS opening chime','Star Trek')]
for f, t, w in real:
    if f in by: out.append(row(f, t, w))
music = re.compile(r'jingle|fanfare|theme|tune|music|song|win-|tuba|sad-ending|game-over|sega', re.I)
packs = collections.OrderedDict()
for x in c:
    if x['grp'] == 'OpenGameArt' and music.search(x['f'] + x['src']) and 'chant' not in x['f'] and 'ghost' not in x['f'] and x['f'] != 'long/fart-symphony' and 'SFX' not in x['src']:
        packs.setdefault((x['src'], x['url']), []).append(x['f'])
out += ["\n## CC0 jingles and fanfares (OpenGameArt)\n", "| Pack | Clips | Files |", "| --- | --- | --- |"]
for (s, u), fs in packs.items(): out.append(f"| [{s}]({u}) | {len(fs)} | " + ", ".join(f"`{f}`" for f in fs) + " |")
open('sounds/SONGS.md', 'w').write("\n".join(out) + "\n")
print(len(cope) + len([r for r in real if r[0] in by]), 'songs;', len(packs), 'packs')
